    /**
     * Method to retrieve the Tenant via TenantFetchOneSummary
     * @param 	summary TenantFetchOneSummary 
     * @return 	TenantFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Tenant getTenant( TenantFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "TenantFetchOneSummary arg cannot be null" );
    	
    	Tenant entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Tenant
        	// --------------------------------------
        	CompletableFuture<Tenant> futureEntity = queryGateway.query(new FindTenantQuery( new LoadTenantFilter( summary.getTenantId() ) ), ResponseTypes.instanceOf(Tenant.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Tenant with id " + summary.getTenantId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


